"use strict";
const WASM = "";
let wasm = null, last = null, selected = null;
const $ = id => document.getElementById(id);
const MOTORS = [["F39T","AeroTech F39T"],["F44W","AeroTech F44W"],["F24W","AeroTech F24W"],["D12","Estes D12"]];
const NUM = ["hold_force_n","mu_static","mu_kinetic","rail_travel_m","rail_tilt_deg","extra_rocket_g","payload_g","parachute_d_m","wind_m_s"];
const NAMES = {"10-nose-cone":"Nose cone","11-upper-tube":"Upper tube","12-coupler":"Coupler","13-fin-can":"Fin can","14-motor-retainer":"Motor retainer","15-guide-collar":"Guide collar","18-motor-spacer":"Motor spacer"};
const store = {
  get(k) { try { return JSON.parse(localStorage.getItem(k)); } catch (e) { return null; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
};

function call(req) {
  const e = wasm.exports, bytes = new TextEncoder().encode(JSON.stringify(req));
  const p = e.alloc(bytes.length);
  new Uint8Array(e.memory.buffer, p, bytes.length).set(bytes);
  const out = e.ground_report(p, bytes.length);
  e.dealloc(p, bytes.length);
  const len = new DataView(e.memory.buffer).getUint32(out, true);
  return JSON.parse(new TextDecoder().decode(new Uint8Array(e.memory.buffer, out + 4, len)));
}

function request() {
  const req = { material: $("material").value, motors: [...document.querySelectorAll(".motors input:checked")].map(i => i.value), weighed_g: {} };
  for (const id of NUM) { const v = $(id).value.trim(); if (v !== "") req[id] = Number(v); }
  document.querySelectorAll("#parts input").forEach(i => { if (i.value.trim() !== "") req.weighed_g[i.dataset.part] = Number(i.value); });
  req.custom_eng = $("custom_eng").value;
  return req;
}

const fmt = (v, d = 0) => (v === null || v === undefined || Number.isNaN(v)) ? "–" : Number(v).toFixed(d);
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]));
const word = s => ({ok:"OK", warn:"CHECK", fail:"FAIL"}[s] || s);

function renderParts(parts) {
  const body = $("parts");
  if (body.dataset.material === $("material").value && body.children.length) return;
  const keep = {}; body.querySelectorAll("input").forEach(i => keep[i.dataset.part] = i.value);
  body.dataset.material = $("material").value;
  body.innerHTML = parts.map(p => `<tr><td>${esc(NAMES[p.name] || p.name)}${p.quantity > 1 ? " ×" + p.quantity : ""}</td><td class="num">${fmt(p.mass_g, 1)}</td><td class="num"><input type="number" min="0" step="0.1" data-part="${esc(p.name)}" aria-label="Weighed mass of ${esc(NAMES[p.name] || p.name)} in grams" value="${esc(keep[p.name] || "")}"></td></tr>`).join("");
}

function rocketSVG(g, s) {
  // True proportions: the fins and body drawn to the same scale as the length.
  const W = 760, L = g.length_mm, sx = (W - 40) / L, x0 = 20, r = g.body_d_mm / 2 * sx, span = g.span_mm * sx, H = Math.round(2 * (r + span) + 80), cy = H / 2;
  const nose = []; const n = 24, ln = g.nose_length_mm, rad = g.body_d_mm / 2, rho = (rad * rad + ln * ln) / (2 * rad);
  for (let i = 0; i <= n; i++) { const x = ln * i / n; const y = Math.sqrt(rho * rho - (ln - x) ** 2) + rad - rho; nose.push([x0 + x * sx, cy - y * sx]); }
  const top = nose.map(p => p.join(",")).join(" "), bottom = nose.slice().reverse().map(p => [p[0], 2 * cy - p[1]].join(",")).join(" ");
  const xe = x0 + L * sx, le = x0 + g.le_station_mm * sx, tick = r + span + 12;
  const fin = (sgn) => `${le},${cy + sgn * r} ${le + g.sweep_mm * sx},${cy + sgn * (r + span)} ${le + (g.sweep_mm + g.tip_mm) * sx},${cy + sgn * (r + span)} ${xe},${cy + sgn * r}`;
  const cg = x0 + s.cg_liftoff_mm * sx, cp = x0 + s.cp_mm * sx;
  return `<svg class="diagram" viewBox="0 0 ${W} ${H}" role="img" aria-label="Side view of the rocket, ${L} mm long. Centre of gravity ${fmt(s.cg_liftoff_mm)} mm from the nose tip; centre of pressure ${fmt(s.cp_mm)} mm; margin ${fmt(s.margin_liftoff_cal, 2)} calibres.">
    <polygon points="${fin(-1)}" fill="#C9C1AE"/><polygon points="${fin(1)}" fill="#C9C1AE"/>
    <polygon points="${top} ${xe},${cy - r} ${xe},${cy + r} ${bottom}" fill="#E9E4D8" stroke="#0F1B2D" stroke-width="1.5"/>
    <line x1="${cg}" y1="${cy - tick}" x2="${cg}" y2="${cy + tick}" stroke="#0F1B2D" stroke-width="2" stroke-dasharray="5 4"/>
    <circle cx="${cg}" cy="${cy}" r="7" fill="#F5F3EE" stroke="#0F1B2D" stroke-width="2"/><path d="M${cg - 7},${cy} A7,7 0 0 1 ${cg},${cy - 7} L${cg},${cy} Z M${cg + 7},${cy} A7,7 0 0 1 ${cg},${cy + 7} L${cg},${cy} Z" fill="#0F1B2D"/>
    <text x="${cg}" y="${cy - tick - 8}" text-anchor="middle" font-size="13" font-weight="600">CG ${fmt(s.cg_liftoff_mm)} mm</text>
    <line x1="${cp}" y1="${cy - tick}" x2="${cp}" y2="${cy + tick}" stroke="#E07A2E" stroke-width="2"/>
    <circle cx="${cp}" cy="${cy}" r="6" fill="#E07A2E"/>
    <text x="${(cg + cp) / 2}" y="${cy + r + 18}" text-anchor="middle" font-size="12.5" fill="#46536A">${fmt(s.margin_liftoff_cal, 2)} calibres</text>
    <text x="${cp}" y="${cy + tick + 20}" text-anchor="middle" font-size="13" font-weight="600" fill="#8A4210">CP ${fmt(s.cp_mm)} mm</text>
  </svg>`;
}

function render(r) {
  last = r;
  const err = $("error");
  if (r.error) {
    // Clear the old prediction so nobody reads numbers for inputs that no longer apply.
    err.textContent = r.error; err.hidden = false;
    $("cards").innerHTML = ""; $("detail").innerHTML = ""; $("flights").innerHTML = "";
    return;
  }
  err.hidden = true;
  renderParts(r.parts);
  const names = r.motors.map(m => m.motor.name);
  if (!names.includes(selected)) selected = names[0];
  $("cards").innerHTML = r.motors.map(m => {
    const f = m.flight;
    return `<button class="mcard" aria-pressed="${m.motor.name === selected}" data-motor="${esc(m.motor.name)}">
      <span class="name">${esc(m.motor.name)}</span><span class="badge ${m.verdict}">${word(m.verdict)}</span>${m.motor.synthetic ? `<span class="badge fail">MADE UP</span>` : ""}
      <dl><dt>Apogee</dt><dd>${fmt(f.apogee_m)} m</dd><dt>Stability</dt><dd>${fmt(m.stability.margin_liftoff_cal, 2)} cal</dd>
      <dt>Thrust/weight</dt><dd>${fmt(m.thrust_to_weight, 1)}:1</dd><dt>Rail exit</dt><dd>${fmt(f.rail_exit && f.rail_exit.speed_m_s, 1)} m/s</dd>
      <dt>Liftoff</dt><dd>${fmt(m.mass_g.liftoff)} g</dd><dt>Delay</dt><dd>${m.best_delay_s === null ? "–" : fmt(m.best_delay_s) + " s"}</dd></dl></button>`;
  }).join("");
  document.querySelectorAll(".mcard").forEach(b => b.onclick = () => { selected = b.dataset.motor; render(last); });
  const m = r.motors.find(x => x.motor.name === selected), f = m.flight;
  $("detail").innerHTML = `<h2>${esc(m.motor.name)}: class ${esc(m.motor.class)}, ${fmt(m.motor.total_impulse_ns, 1)} N·s over ${fmt(m.motor.burn_time_s, 2)} s${m.motor.synthetic ? " (MADE-UP test curve: not a real motor)" : ""}</h2>
    <ul class="checks">${m.checks.map(c => `<li><b class="${c.status}">${word(c.status)}</b><span>${esc(c.check)}</span></li>`).join("")}</ul>
    ${rocketSVG(r.geometry, m.stability)}
    <table style="margin-top:8px"><tbody>
      <tr><td>Time to apogee</td><td class="num">${fmt(f.time_to_apogee_s, 1)} s</td><td>Max speed</td><td class="num">${fmt(f.max_speed_m_s, 1)} m/s (Mach ${fmt(f.max_mach, 2)})</td></tr>
      <tr><td>Descent under the parachute</td><td class="num">${fmt(f.descent_time_s)} s, landing at ${fmt(m.landing_speed_m_s,1)} m/s</td><td>Drift in the wind</td><td class="num">${fmt(m.drift_m)} m</td></tr>
      <tr><td>Margin at burnout</td><td class="num">${fmt(m.stability.margin_burnout_cal, 2)} cal</td><td>Mass at burnout</td><td class="num">${fmt(m.mass_g.burnout)} g</td></tr>
    </tbody></table>`;
  const fm = $("flight_motor");
  const keepM = fm.value || (store.get("rockoon-flights") || {}).motor || selected;
  fm.innerHTML = names.map(n => `<option${n === keepM ? " selected" : ""}>${esc(n)}</option>`).join("");
  renderFlights();
}

const ROWS = [["apogee_m","Apogee (m)",0],["time_to_apogee_s","Time to apogee (s)",1],["descent_time_s","Descent time (s)",0]];
function renderFlights() {
  if (!last || last.error) return;
  const saved = store.get("rockoon-flights") || {};
  const m = last.motors.find(x => x.motor.name === $("flight_motor").value) || last.motors[0];
  $("flights").innerHTML = ROWS.map(([k, label, d]) => {
    const pred = m.flight[k];
    const cells = [0, 1, 2].map(i => {
      const v = (saved[k] || [])[i] ?? "";
      const diff = v !== "" && pred ? ` <small class="${Math.abs(v / pred - 1) > 0.2 ? "warn" : "ok"}">${(v / pred - 1 >= 0 ? "+" : "") + fmt((v / pred - 1) * 100)}%</small>` : "";
      return `<td class="num"><input type="number" step="0.1" min="0" data-k="${k}" data-i="${i}" aria-label="${label}, flight ${i + 1}" value="${esc(v)}">${diff}</td>`;
    }).join("");
    return `<tr><td>${label}</td><td class="num">${fmt(pred, d)}</td>${cells}</tr>`;
  }).join("");
  document.querySelectorAll("#flights input").forEach(i => i.onchange = () => {
    const s = store.get("rockoon-flights") || {};
    s.motor = $("flight_motor").value; s[i.dataset.k] = s[i.dataset.k] || ["", "", ""];
    s[i.dataset.k][+i.dataset.i] = i.value === "" ? "" : Number(i.value);
    store.set("rockoon-flights", s); renderFlights();
  });
}

function csvText() {
  const saved = store.get("rockoon-flights") || {}, m = last.motors.find(x => x.motor.name === $("flight_motor").value) || last.motors[0];
  const lines = ["measure,predicted,flight_1,flight_2,flight_3"];
  for (const [k, label] of ROWS) lines.push([label, m.flight[k], ...[0, 1, 2].map(i => (saved[k] || [])[i] ?? "")].join(","));
  lines.push("", "motor," + m.motor.name, "liftoff_g," + m.mass_g.liftoff, "stability_cal," + m.stability.margin_liftoff_cal, "label,desk simulation prediction vs measured flights");
  return lines.join("\n") + "\n";
}

function csv() {
  const text = csvText(), box = $("csvtext");
  box.value = text; box.hidden = false;
  const done = msg => { $("copied").textContent = msg; };
  try {
    navigator.clipboard.writeText(text).then(() => done("Copied."), () => { box.select(); done("Select the text below and copy it."); });
  } catch (e) { box.select(); done("Select the text below and copy it."); }
}

let timer = null;
function update() {
  clearTimeout(timer);
  timer = setTimeout(() => {
    try { render(call(request())); }
    catch (e) { render({ error: "The simulator stopped (" + e.message + "). Reload the page." }); }
  }, 120);
}

async function start() {
  $("motors").innerHTML = MOTORS.map(([id, name], i) => `<label><input type="checkbox" value="${id}" checked> ${name}</label>`).join("");
  const bin = Uint8Array.from(atob(WASM), c => c.charCodeAt(0));
  wasm = (await WebAssembly.instantiate(bin, {})).instance;
  // One listener for every field, including the parts table built later.
  document.addEventListener("input", e => { if (e.target.matches("input, select, textarea") && !e.target.closest("#flights")) update(); });
  $("flight_motor").onchange = () => { const s = store.get("rockoon-flights") || {}; s.motor = $("flight_motor").value; store.set("rockoon-flights", s); renderFlights(); };
  $("csv").onclick = csv;
  $("clear").onclick = () => { store.set("rockoon-flights", {}); renderFlights(); };
  render(call(request()));
}
start().catch(e => {
  const err = $("error");
  err.textContent = "This viewer did not let the simulator start (" + e + "). Open web/dist/workbook.html from the repository in Chrome, Edge, Firefox or Safari: it runs offline, with nothing to install.";
  err.hidden = false;
});
